--- 是否要隐藏 活动左侧栏的日期显示, 目前只有 推广员活动需要隐藏
-- todo 万一未来这个需求扩大化, 还是要正式地走后端;
---@return boolean
ActivityConstants.IsHideDay = function( type_ )
    if checkNumber(type_) == ActivityConstants.ActivityType.Promoter 
    or checkNumber(type_) == ActivityConstants.ActivityType.ClayFigure
    or checkNumber(type_) == ActivityConstants.ActivityType.SkipUrl
    or checkNumber(type_) == ActivityConstants.ActivityType.CustomTrain
    then 
        return true
    end
    return false
end



return ActivityConstants
